      "date": "2033-08",
      "event": "FDA approves oral semaglutide for alcohol use disorder; telehealth 'Reset' plans pitching the same pill for sports betting and compulsive shopping pass one million subscribers by year-end",
      "driver": "new_indications: compulsive_behaviour"
    },
    {
      "date": "2033-10",
      "event": "Licensed 'metabolic health' microdose plans for adults without obesity reach about nine million subscribers, as longevity clinics in Austin, Miami and Scottsdale make low-dose semaglutide a standard line on the lab panel",
      "driver": "new_indications: longevity_wellness; cultural_response: class_stratification"
    },
    {
      "date": "2033-11",
      "event": "CDC links counterfeit Mounjaro and Ozempic pens filled with rapid-acting insulin to ~1,100 emergency visits and 19 deaths in 31 states, mostly among people without diabetes who were microdosing",
      "driver": "market_shock: generic_flood_counterfeits"
    },
    {
      "date": "2034-02",
      "event": "Benefits survey finds 19% of large employers reimburse calm or 'Reset' platform fees through lifestyle spending accounts; a former call-centre agent sues in Ohio federal court, alleging promotions favoured monitored-track enrollees",
      "driver": "personality_layer: employer_encouraged"
    },
    {
      "date": "2034-06",
      "event": "Eleven states have now enacted bans on weight-loss incretin prescribing for children under 12 and in-person rules for low-BMI adult prescriptions, as FTC and FDA consent orders bar four telehealth platforms from mood and compulsion claims",
      "driver": "state_action: restriction"
    }
  ],
  "open_tensions": [
